#!/bin/bash
set -e

# Tapering schedules for medicines (e.g. post-op steroid taper:
# QID x1wk -> TDS x1wk -> BD x1wk -> OD x1wk, then stop).
# - New taper_group_id/taper_step columns on prescriptions (already
#   applied live to both production and training).
# - Doctor's Prescription section: 'Add as Tapering Schedule instead'
#   toggle opens a step builder (default 4-step QID->TDS->BD->OD,
#   editable), using the same drug/dosage/eye already entered.
# - Related rows display as one grouped block on screen and print
#   as one merged row with a (Taper) badge, instead of looking like
#   several unrelated prescriptions.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/(main)/consultation"
echo "" | base64 -d > "app/(main)/consultation/actions.js"
echo "Wrote app/(main)/consultation/actions.js"

mkdir -p "app/consultation/[id]"
echo "" | base64 -d > "app/consultation/[id]/consultation-form.js"
echo "Wrote app/consultation/[id]/consultation-form.js"

mkdir -p "app/print-templates"
echo "" | base64 -d > "app/print-templates/actions.js"
echo "Wrote app/print-templates/actions.js"

git add "app/(main)/consultation/actions.js" "app/consultation/[id]/consultation-form.js" "app/print-templates/actions.js"
git commit -m "Add medicine tapering schedules: grouped multi-step prescriptions, screen + print"
git push

echo "Done."
